const listChildTaskRuns = `-- name: ListChildTaskRuns :many
SELECT
    id, tenant_id, workspace_id, created_by, run_type, subject_type, subject_id, is_internal, hidden_at, status, error_code, error_message, state_version, started_at, finished_at, created_at, updated_at, root_task_id, parent_task_id
FROM task_runs
WHERE
    tenant_id = $1
    AND workspace_id IS NOT DISTINCT FROM $2::varchar
    AND parent_task_id = $3::varchar
ORDER BY
    created_at,
    id
`

type ListChildTaskRunsParams struct {
	TenantID    string
	WorkspaceID *string
	RelatedID   string
}

func (q *Queries) ListChildTaskRuns(ctx context.Context, arg ListChildTaskRunsParams) ([]TaskRun, error) {
	rows, err := q.db.Query(ctx, listChildTaskRuns, arg.TenantID, arg.WorkspaceID, arg.RelatedID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TaskRun{}
	for rows.Next() {
		var i TaskRun
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.WorkspaceID,
			&i.CreatedBy,
			&i.RunType,
			&i.SubjectType,
			&i.SubjectID,
			&i.IsInternal,
			&i.HiddenAt,
			&i.Status,
			&i.ErrorCode,
			&i.ErrorMessage,
			&i.StateVersion,
			&i.StartedAt,
			&i.FinishedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RootTaskID,
			&i.ParentTaskID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

